"use client";

import React, { useState, useEffect } from 'react';
import {
  User, Mail, Shield, Sliders, Music, Check, Share2, LogOut,
  Sparkles, CheckCircle2, ChevronRight, Save, Headphones
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useNotification } from '../context/NotificationContext';
import { getSpotifyAuthUrl } from '../services/spotify';

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const handler = () => setIsMobile(window.innerWidth < 768);
    handler();
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);
  return isMobile;
}

export default function DashboardView() {
  const { currentUser, loginWithGoogle, logout } = useAuth();
  const { showPrompt } = useNotification();
  const isMobile = useIsMobile();

  // Local editable form state & preferences with persistence
  const [displayName, setDisplayName] = useState(currentUser?.displayName || '');
  const [bio, setBio] = useState('');
  const [audioQuality, setAudioQuality] = useState('320');
  const [autoplay, setAutoplay] = useState(true);
  const [explicitContent, setExplicitContent] = useState(true);
  const [audioNormalization, setAudioNormalization] = useState(false);
  const [saving, setSaving] = useState(false);
  const [savedSuccess, setSavedSuccess] = useState(false);

  useEffect(() => {
    if (currentUser?.displayName) {
      setDisplayName(currentUser.displayName);
    }
    try {
      const savedBio = localStorage.getItem(`wavex_bio_${currentUser?.uid}`);
      if (savedBio) setBio(savedBio);

      const savedQuality = localStorage.getItem('wavex_audio_quality');
      if (savedQuality) setAudioQuality(savedQuality);

      const savedAutoplay = localStorage.getItem('wavex_autoplay');
      if (savedAutoplay !== null) setAutoplay(savedAutoplay === 'true');

      const savedExplicit = localStorage.getItem('wavex_explicit');
      if (savedExplicit !== null) setExplicitContent(savedExplicit === 'true');

      const savedNorm = localStorage.getItem('wavex_normalization');
      if (savedNorm !== null) setAudioNormalization(savedNorm === 'true');
    } catch {}
  }, [currentUser]);

  const handleSavePreferences = () => {
    setSaving(true);
    try {
      if (currentUser?.uid) {
        localStorage.setItem(`wavex_bio_${currentUser.uid}`, bio);
      }
      localStorage.setItem('wavex_audio_quality', audioQuality);
      localStorage.setItem('wavex_autoplay', String(autoplay));
      localStorage.setItem('wavex_explicit', String(explicitContent));
      localStorage.setItem('wavex_normalization', String(audioNormalization));

      setSavedSuccess(true);
      showPrompt('Preferences saved successfully', 'success');
      setTimeout(() => setSavedSuccess(false), 3000);
    } catch {
      showPrompt('Failed to save preferences', 'error');
    } finally {
      setSaving(false);
    }
  };

  if (!currentUser) {
    return (
      <div style={{
        padding: 40,
        color: "var(--wx-text)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "70vh",
      }}>
        <div style={{
          width: 64, height: 64, borderRadius: 20,
          background: 'rgba(0,229,255,0.15)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          marginBottom: 20,
        }}>
          <User size={32} color="var(--wx-cyan)" />
        </div>
        <h1 style={{ fontSize: isMobile ? 28 : 40, fontWeight: 900, marginBottom: 12, textAlign: 'center' }}>
          WaveX Account
        </h1>
        <p style={{ color: "var(--wx-text-muted)", marginBottom: 32, fontSize: 15, textAlign: 'center', maxWidth: 440 }}>
          Log in with your Google account to sync your playlists, liked tracks, and personalized listening preferences across devices.
        </p>
        <button
          onClick={loginWithGoogle}
          style={{
            padding: "14px 36px",
            borderRadius: 14,
            background: "linear-gradient(135deg, var(--wx-cyan), var(--wx-cyan-dark))",
            color: "#080C14",
            border: "none",
            fontSize: 15,
            fontWeight: 900,
            cursor: "pointer",
            boxShadow: '0 0 24px rgba(0,229,255,0.4)',
          }}
        >
          Sign In with Google
        </button>
      </div>
    );
  }

  const photoURL = currentUser?.photoURL || (currentUser as any)?.providerData?.[0]?.photoURL;
  const highResPhoto = photoURL?.replace(/=s96-c/, "=s400-c") || photoURL || `https://api.dicebear.com/7.x/initials/svg?seed=${currentUser?.displayName || 'User'}`;
  const px = isMobile ? '16px' : 'clamp(20px, 3vw, 40px)';

  return (
    <div style={{ padding: `24px ${px} 120px`, maxWidth: 1000, margin: "0 auto" }}>
      {/* Sticky top breadcrumb */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 8,
        fontSize: 13, fontWeight: 700, color: 'var(--wx-text-muted)',
        marginBottom: 24,
      }}>
        <span>Account</span>
        <ChevronRight size={14} />
        <span style={{ color: 'var(--wx-cyan)' }}>Profile &amp; Preferences</span>
      </div>

      {/* Hero Profile Card */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(0,229,255,0.12) 0%, var(--wx-surface-card) 60%)',
        border: '1px solid rgba(0,229,255,0.25)',
        borderRadius: 24,
        padding: isMobile ? 24 : 36,
        marginBottom: 32,
        boxShadow: '0 0 32px rgba(0,229,255,0.06)',
        display: 'flex',
        flexDirection: isMobile ? 'column' : 'row',
        alignItems: isMobile ? 'center' : 'center',
        gap: isMobile ? 20 : 32,
        textAlign: isMobile ? 'center' : 'left',
      }}>
        <div style={{ position: 'relative', flexShrink: 0 }}>
          <img
            src={highResPhoto}
            alt="User Avatar"
            onError={(e) => { e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${currentUser?.displayName || 'User'}`; }}
            style={{
              width: isMobile ? 100 : 130,
              height: isMobile ? 100 : 130,
              borderRadius: "50%",
              border: "3px solid var(--wx-cyan)",
              boxShadow: "0 0 28px rgba(0,229,255,0.35)",
              objectFit: 'cover',
            }}
          />
          {/* Online Indicator Dot */}
          <div style={{
            position: 'absolute', bottom: 6, right: 6,
            width: 18, height: 18, borderRadius: '50%',
            background: '#10b981',
            border: '3px solid var(--wx-surface-card)',
            boxShadow: '0 0 10px rgba(16,185,129,0.8)',
          }} />
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, justifyContent: isMobile ? 'center' : 'flex-start', marginBottom: 8, flexWrap: 'wrap' }}>
            <span style={{
              background: 'rgba(0,229,255,0.15)',
              border: '1px solid rgba(0,229,255,0.3)',
              color: 'var(--wx-cyan)',
              borderRadius: 9999,
              padding: '4px 12px',
              fontSize: 11,
              fontWeight: 900,
              letterSpacing: 1,
              textTransform: 'uppercase',
            }}>
              WaveX Member
            </span>
            <span style={{ fontSize: 12, color: 'var(--wx-text-muted)', display: 'flex', alignItems: 'center', gap: 4 }}>
              <CheckCircle2 size={13} color="#10b981" /> Verified Account
            </span>
          </div>

          <h1 style={{
            fontSize: isMobile ? 28 : 40,
            fontWeight: 900,
            margin: "0 0 6px",
            color: "var(--wx-text)",
            letterSpacing: -0.5,
            lineHeight: 1.1,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
          }}>
            {currentUser.displayName || 'WaveX User'}
          </h1>
          <p style={{ color: "var(--wx-text-muted)", fontSize: 14, margin: 0 }}>
            {currentUser.email}
          </p>
        </div>
      </div>

      {/* Grid of Setting Sections */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
        {/* Section 1: Profile Information */}
        <div style={{
          background: 'var(--wx-surface-card)',
          border: '1px solid var(--wx-border)',
          borderRadius: 20,
          padding: isMobile ? 20 : 28,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
            <User size={20} color="var(--wx-cyan)" />
            <h2 style={{ fontSize: 18, fontWeight: 900, margin: 0, color: 'var(--wx-text)' }}>
              Profile Information
            </h2>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 18 }}>
            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 700, color: 'var(--wx-text-muted)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                Display Name
              </label>
              <input
                type="text"
                value={displayName}
                onChange={(e) => setDisplayName(e.target.value)}
                placeholder="Your name"
                style={{
                  width: '100%',
                  background: 'var(--wx-surface)',
                  border: '1px solid var(--wx-border)',
                  borderRadius: 12,
                  padding: '12px 16px',
                  color: 'var(--wx-text)',
                  fontSize: 14,
                  fontWeight: 600,
                  outline: 'none',
                }}
              />
            </div>

            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 700, color: 'var(--wx-text-muted)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                Email Address
              </label>
              <input
                type="email"
                value={currentUser.email || ''}
                readOnly
                disabled
                style={{
                  width: '100%',
                  background: 'rgba(255,255,255,0.03)',
                  border: '1px solid var(--wx-border)',
                  borderRadius: 12,
                  padding: '12px 16px',
                  color: 'var(--wx-text-muted)',
                  fontSize: 14,
                  fontWeight: 600,
                  cursor: 'not-allowed',
                }}
              />
            </div>

            <div style={{ gridColumn: isMobile ? '1' : '1 / -1' }}>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 700, color: 'var(--wx-text-muted)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                Bio &amp; Listening Vibe
              </label>
              <input
                type="text"
                value={bio}
                onChange={(e) => setBio(e.target.value)}
                placeholder="A short note about your music taste (e.g. Deep house lover, acoustic explorer)..."
                style={{
                  width: '100%',
                  background: 'var(--wx-surface)',
                  border: '1px solid var(--wx-border)',
                  borderRadius: 12,
                  padding: '12px 16px',
                  color: 'var(--wx-text)',
                  fontSize: 14,
                  fontWeight: 600,
                  outline: 'none',
                }}
              />
            </div>
          </div>
        </div>

        {/* Section 2: Audio & Playback Preferences */}
        <div style={{
          background: 'var(--wx-surface-card)',
          border: '1px solid var(--wx-border)',
          borderRadius: 20,
          padding: isMobile ? 20 : 28,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
            <Sliders size={20} color="var(--wx-cyan)" />
            <h2 style={{ fontSize: 18, fontWeight: 900, margin: 0, color: 'var(--wx-text)' }}>
              Audio &amp; Playback Preferences
            </h2>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            {/* Audio Quality */}
            <div style={{
              display: 'flex',
              alignItems: isMobile ? 'flex-start' : 'center',
              flexDirection: isMobile ? 'column' : 'row',
              justifyContent: 'space-between',
              padding: '16px 20px',
              background: 'var(--wx-surface)',
              borderRadius: 14,
              border: '1px solid var(--wx-border)',
              gap: 12,
            }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, color: 'var(--wx-text)' }}>Streaming Audio Quality</div>
                <div style={{ fontSize: 13, color: 'var(--wx-text-muted)', marginTop: 2 }}>
                  Higher bitrates deliver studio fidelity with rich dynamic range.
                </div>
              </div>
              <select
                value={audioQuality}
                onChange={(e) => setAudioQuality(e.target.value)}
                style={{
                  background: 'var(--wx-surface-card)',
                  color: 'var(--wx-cyan)',
                  border: '1px solid var(--wx-border)',
                  padding: '8px 16px',
                  borderRadius: 10,
                  fontWeight: 700,
                  fontSize: 13,
                  outline: 'none',
                  cursor: 'pointer',
                }}
              >
                <option value="320">320 kbps (Lossless / Hi-Fi)</option>
                <option value="160">160 kbps (High Fidelity)</option>
                <option value="96">96 kbps (Data Saver)</option>
              </select>
            </div>

            {/* Autoplay Toggle */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              padding: '16px 20px',
              background: 'var(--wx-surface)',
              borderRadius: 14,
              border: '1px solid var(--wx-border)',
            }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, color: 'var(--wx-text)' }}>Autoplay Next Track</div>
                <div style={{ fontSize: 13, color: 'var(--wx-text-muted)', marginTop: 2 }}>
                  Keep the music flowing with continuous queue playback.
                </div>
              </div>
              <input
                type="checkbox"
                checked={autoplay}
                onChange={(e) => setAutoplay(e.target.checked)}
                style={{ width: 20, height: 20, cursor: 'pointer', accentColor: 'var(--wx-cyan)' }}
              />
            </div>

            {/* Explicit Filter */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              padding: '16px 20px',
              background: 'var(--wx-surface)',
              borderRadius: 14,
              border: '1px solid var(--wx-border)',
            }}>
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, color: 'var(--wx-text)' }}>Allow Explicit Content</div>
                <div style={{ fontSize: 13, color: 'var(--wx-text-muted)', marginTop: 2 }}>
                  Show and stream tracks with explicit rating labels.
                </div>
              </div>
              <input
                type="checkbox"
                checked={explicitContent}
                onChange={(e) => setExplicitContent(e.target.checked)}
                style={{ width: 20, height: 20, cursor: 'pointer', accentColor: 'var(--wx-cyan)' }}
              />
            </div>
          </div>
        </div>

        {/* Section 3: Integrations & Connected Services */}
        <div style={{
          background: 'var(--wx-surface-card)',
          border: '1px solid var(--wx-border)',
          borderRadius: 20,
          padding: isMobile ? 20 : 28,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
            <Share2 size={20} color="#1DB954" />
            <h2 style={{ fontSize: 18, fontWeight: 900, margin: 0, color: 'var(--wx-text)' }}>
              Connected Services &amp; Import
            </h2>
          </div>

          <div style={{
            display: 'flex',
            alignItems: isMobile ? 'flex-start' : 'center',
            flexDirection: isMobile ? 'column' : 'row',
            justifyContent: 'space-between',
            padding: '18px 20px',
            background: 'var(--wx-surface)',
            borderRadius: 14,
            border: '1px solid var(--wx-border)',
            gap: 16,
          }}>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                <span style={{ fontSize: 15, fontWeight: 800, color: 'var(--wx-text)' }}>Import from Spotify</span>
                <span style={{ background: 'rgba(29,185,84,0.15)', color: '#1DB954', fontSize: 11, fontWeight: 800, padding: '2px 8px', borderRadius: 9999 }}>Official Integration</span>
              </div>
              <div style={{ fontSize: 13, color: 'var(--wx-text-muted)' }}>
                Bring your Spotify saved playlists and top tracks straight into your WaveX library.
              </div>
            </div>

            <button
              onClick={() => {
                const url = getSpotifyAuthUrl();
                if (url) window.location.href = url;
                else alert("Please configure a Spotify Client ID in src/services/spotify.ts");
              }}
              style={{
                background: '#1DB954',
                color: '#fff',
                border: 'none',
                borderRadius: 12,
                padding: '10px 22px',
                fontWeight: 900,
                fontSize: 13,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                flexShrink: 0,
                boxShadow: '0 0 16px rgba(29,185,84,0.3)',
              }}
            >
              <Share2 size={16} /> Connect Spotify
            </button>
          </div>
        </div>

        {/* Section 4: Actions & Danger Zone */}
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 16,
          marginTop: 8,
        }}>
          <button
            onClick={logout}
            style={{
              background: 'rgba(239,68,68,0.1)',
              border: '1px solid rgba(239,68,68,0.3)',
              color: '#ef4444',
              borderRadius: 12,
              padding: '12px 24px',
              fontWeight: 800,
              fontSize: 14,
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: 8,
            }}
          >
            <LogOut size={16} /> Log Out
          </button>

          <button
            onClick={handleSavePreferences}
            disabled={saving}
            style={{
              background: savedSuccess
                ? '#10b981'
                : 'linear-gradient(135deg, var(--wx-cyan), var(--wx-cyan-dark))',
              color: '#080C14',
              border: 'none',
              borderRadius: 12,
              padding: '12px 32px',
              fontWeight: 900,
              fontSize: 14,
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              boxShadow: savedSuccess
                ? '0 0 24px rgba(16,185,129,0.5)'
                : '0 0 24px rgba(0,229,255,0.4)',
              transition: 'all 0.2s ease',
            }}
          >
            {savedSuccess ? <Check size={18} /> : <Save size={18} />}
            {savedSuccess ? 'Preferences Saved!' : saving ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>
    </div>
  );
}
