"use client";

import React, { useEffect, useState } from 'react';
import { Heart, Music2, Play, Shuffle, Sparkles, Plus, Loader2 } from 'lucide-react';
import TrackList from '../components/TrackList';
import { usePlayer } from '../context/PlayerContext';
import { searchSongs, API_BASE_URL } from '../services/api';
import { useNotification } from '../context/NotificationContext';
import { useAuth } from '../context/AuthContext';
import { usePlaylists } from '../context/PlaylistContext';
import { Track, Playlist } from '../types/music';

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const handler = () => setIsMobile(window.innerWidth < 768);
    handler();
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);
  return isMobile;
}

function formatTotalDuration(seconds: number): string {
  if (!seconds || isNaN(seconds)) return '';
  const hrs = Math.floor(seconds / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  if (hrs > 0) return `${hrs} hr ${mins} min`;
  return `${mins} min`;
}

interface PlaylistViewProps {
  activeView: string;
  activePlaylist: Playlist | null;
  setActivePlaylist: (pl: Playlist | null) => void;
  setActiveView?: (view: string) => void;
}

export default function PlaylistView({ activeView, activePlaylist, setActivePlaylist, setActiveView }: PlaylistViewProps) {
  const { liked, playTrack, setShuffle } = usePlayer();
  const { showPrompt } = useNotification();
  const { currentUser } = useAuth();
  const { addTrack } = usePlaylists();
  const isMobile = useIsMobile();
  const [playlistTracks, setPlaylistTracks] = useState<Track[]>([]);
  const [loadingTracks, setLoadingTracks] = useState(false);
  const [addingIds, setAddingIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<Track[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  useEffect(() => {
    async function getTracks() {
      if (activeView === "liked") {
        setLoadingTracks(true);
        if (currentUser) {
          try {
            const res = await fetch(`${API_BASE_URL}/api/likes?userId=${currentUser.uid}`);
            const data = await res.json();
            if (Array.isArray(data)) {
              setPlaylistTracks(data.map((t: any) => ({ ...t, id: t.trackId || t.id })));
            } else {
              setPlaylistTracks([]);
            }
          } catch (e) {
            console.error("Failed to load liked songs", e);
            setPlaylistTracks([]);
          }
        } else {
          setPlaylistTracks([]);
        }
        setLoadingTracks(false);
        return;
      }
      if (activePlaylist?.id === "trending") {
        setLoadingTracks(true);
        const tracks = await searchSongs("trending pop songs");
        setPlaylistTracks(tracks);
        setLoadingTracks(false);
        return;
      }
      if (activePlaylist?.id === "top") {
        setLoadingTracks(true);
        const tracks = await searchSongs("top hits 2024");
        setPlaylistTracks(tracks);
        setLoadingTracks(false);
        return;
      }
      if (activePlaylist?.tracks && activePlaylist.tracks.length > 0) {
        const mappedTracks = activePlaylist.tracks.map((t: any) => ({
          ...t,
          id: t.trackId || t.id,
        }));
        setPlaylistTracks(mappedTracks);
      } else {
        setPlaylistTracks([]);
      }
    }
    getTracks();
  }, [activePlaylist?.id, activePlaylist?.tracks?.length, activeView, liked, currentUser]);

  useEffect(() => {
    if (!searchQuery || searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }
    const timer = setTimeout(async () => {
      setIsSearching(true);
      const res = await searchSongs(searchQuery);
      setSearchResults(res.slice(0, 10));
      setIsSearching(false);
    }, 500);
    return () => clearTimeout(timer);
  }, [searchQuery]);

  const handleAddTrack = async (track: Track) => {
    if (!activePlaylist || addingIds.has(track.id)) return;
    const prevPlaylist = { ...activePlaylist };
    const prevTracks = [...playlistTracks];
    setAddingIds(prev => new Set(prev).add(track.id));

    const newTrackForPlaylist = { ...track, trackId: track.id };
    setActivePlaylist({
      ...activePlaylist,
      tracks: [...(activePlaylist.tracks || []), newTrackForPlaylist]
    });
    setPlaylistTracks(prev => [...prev, track]);
    showPrompt(`Added "${track.title}" to playlist.`, "success");
    try {
      await addTrack(activePlaylist._id || activePlaylist.id, track);
    } catch {
      setActivePlaylist(prevPlaylist);
      setPlaylistTracks(prevTracks);
    } finally {
      setAddingIds(prev => {
        const n = new Set(prev);
        n.delete(track.id);
        return n;
      });
    }
  };

  const handlePlayAll = () => {
    if (playlistTracks.length > 0) {
      playTrack(playlistTracks[0], playlistTracks);
    }
  };

  const handleShufflePlay = () => {
    if (playlistTracks.length > 0) {
      setShuffle(true);
      const randomIndex = Math.floor(Math.random() * playlistTracks.length);
      playTrack(playlistTracks[randomIndex], playlistTracks);
    }
  };

  const totalDuration = playlistTracks.reduce((acc, t) => acc + (t.duration || 0), 0);
  const formattedDuration = formatTotalDuration(totalDuration);

  const isLikedView = activeView === "liked";
  const headerTitle = isLikedView ? "Liked Songs" : (activePlaylist?.name || "Playlist");
  const px = isMobile ? '16px' : 'clamp(20px, 3vw, 40px)';

  return (
    <div style={{ paddingBottom: 100 }}>
      {/* Stitch Hero Banner */}
      <div style={{
        position: "relative",
        background: isLikedView
          ? "linear-gradient(135deg, rgba(255, 0, 128, 0.25) 0%, rgba(121, 40, 202, 0.25) 50%, rgba(0, 229, 255, 0.15) 100%)"
          : "linear-gradient(135deg, rgba(0, 229, 255, 0.2) 0%, rgba(11, 16, 28, 0.8) 100%)",
        borderBottom: "1px solid var(--wx-border)",
        padding: isMobile ? "32px 16px 24px" : "48px 40px 36px",
        marginBottom: 28,
        overflow: "hidden",
      }}>
        {/* Soft Background Blur Artwork */}
        {playlistTracks[0]?.cover && (
          <div style={{
            position: "absolute",
            inset: 0,
            background: `url(${playlistTracks[0].cover})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
            filter: "blur(90px) brightness(0.25)",
            transform: "scale(1.2)",
            opacity: 0.5,
            zIndex: 0,
            pointerEvents: "none",
          }} />
        )}

        <div style={{
          display: "flex",
          alignItems: isMobile ? "center" : "flex-end",
          flexDirection: isMobile ? "column" : "row",
          gap: isMobile ? 20 : 32,
          position: "relative",
          zIndex: 1,
          textAlign: isMobile ? "center" : "left",
        }}>
          {/* Cover Art Box */}
          <div style={{
            width: isMobile ? 150 : 210,
            height: isMobile ? 150 : 210,
            borderRadius: 20,
            background: isLikedView
              ? "linear-gradient(135deg, #FF0080, #7928CA)"
              : "var(--wx-surface-card)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: isLikedView
              ? "0 16px 48px rgba(255,0,128,0.3)"
              : "0 16px 48px rgba(0,0,0,0.6)",
            flexShrink: 0,
            border: "1px solid rgba(255,255,255,0.15)",
            overflow: "hidden",
          }}>
            {isLikedView ? (
              <Heart size={isMobile ? 56 : 80} fill="#fff" color="#fff" />
            ) : playlistTracks[0]?.cover ? (
              <img src={playlistTracks[0].cover} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            ) : (
              <Music2 size={isMobile ? 56 : 72} color="var(--wx-cyan)" />
            )}
          </div>

          {/* Metadata */}
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              fontSize: 12,
              fontWeight: 800,
              letterSpacing: 1.5,
              textTransform: "uppercase",
              color: isLikedView ? "#FF0080" : "var(--wx-cyan)",
              marginBottom: 8,
            }}>
              <Sparkles size={13} />
              {isLikedView ? "Personal Library" : "Playlist"}
            </div>

            <h1 style={{
              fontSize: isMobile ? 32 : "clamp(36px, 4.5vw, 64px)",
              fontWeight: 900,
              margin: "0 0 12px",
              color: "var(--wx-text)",
              letterSpacing: -1,
              lineHeight: 1.05,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: isMobile ? 'normal' : 'nowrap',
            }}>
              {headerTitle}
            </h1>

            <div style={{
              display: "flex",
              alignItems: "center",
              justifyContent: isMobile ? "center" : "flex-start",
              gap: 8,
              fontSize: 13,
              color: "var(--wx-text-muted)",
              fontWeight: 700,
              flexWrap: 'wrap',
            }}>
              {currentUser?.photoURL ? (
                <img src={currentUser.photoURL} style={{ width: 22, height: 22, borderRadius: "50%", border: "1px solid var(--wx-border)" }} alt="" />
              ) : (
                <div style={{ width: 22, height: 22, borderRadius: '50%', background: 'var(--wx-cyan)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, fontWeight: 900, color: '#080C14' }}>
                  {currentUser?.displayName?.[0] || 'W'}
                </div>
              )}
              <span style={{ color: "var(--wx-text)" }}>{currentUser?.displayName || 'WaveX User'}</span>
              <span>•</span>
              <span>{playlistTracks.length} song{playlistTracks.length !== 1 ? 's' : ''}</span>
              {formattedDuration && (
                <>
                  <span>•</span>
                  <span>{formattedDuration}</span>
                </>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Main Content & Action Bar */}
      <div style={{ padding: `0 ${px}` }}>
        {/* Play & Shuffle Buttons */}
        {playlistTracks.length > 0 && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 28 }}>
            <button
              onClick={handlePlayAll}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                background: 'linear-gradient(135deg, var(--wx-cyan), var(--wx-cyan-dark))',
                color: '#080C14',
                border: 'none',
                borderRadius: 14,
                padding: '12px 28px',
                fontSize: 14,
                fontWeight: 900,
                cursor: 'pointer',
                boxShadow: '0 0 24px rgba(0,229,255,0.4)',
                transition: 'all 0.15s ease',
              }}
            >
              <Play size={18} fill="#080C14" /> Play All
            </button>

            <button
              onClick={handleShufflePlay}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 8,
                background: 'var(--wx-surface-card)',
                color: 'var(--wx-text)',
                border: '1px solid var(--wx-border)',
                borderRadius: 14,
                padding: '12px 22px',
                fontSize: 14,
                fontWeight: 700,
                cursor: 'pointer',
                transition: 'all 0.15s ease',
              }}
            >
              <Shuffle size={17} color="var(--wx-cyan)" /> Shuffle
            </button>
          </div>
        )}

        {/* Tracks List or Empty State */}
        <div style={{ marginBottom: 40 }}>
          {loadingTracks ? (
            <div style={{ padding: "60px 0", textAlign: "center", color: "var(--wx-text-muted)" }}>
              <div style={{ width: 36, height: 36, border: '3px solid var(--wx-cyan)', borderTopColor: 'transparent', borderRadius: '50%', animation: 'wx-spin 1s linear infinite', margin: '0 auto 16px' }} />
              <div style={{ fontSize: 14, fontWeight: 600 }}>Loading your library...</div>
            </div>
          ) : playlistTracks.length === 0 ? (
            <div style={{
              textAlign: "center",
              padding: "70px 20px",
              background: 'var(--wx-surface-card)',
              borderRadius: 24,
              border: '1px solid var(--wx-border)',
            }}>
              {isLikedView ? (
                <Heart size={54} color="#FF0080" style={{ opacity: 0.4, margin: '0 auto 16px' }} />
              ) : (
                <Music2 size={54} color="var(--wx-cyan)" style={{ opacity: 0.4, margin: '0 auto 16px' }} />
              )}
              <div style={{ fontSize: 20, fontWeight: 900, color: 'var(--wx-text)', marginBottom: 8 }}>
                {isLikedView ? "Songs you like will appear here" : "This playlist is empty"}
              </div>
              <p style={{ color: "var(--wx-text-muted)", fontSize: 14, maxWidth: 420, margin: "0 auto 24px" }}>
                {isLikedView
                  ? "Save songs to your Liked Songs collection by clicking the heart icon on any track while searching or playing."
                  : "Add songs to this playlist using the search section below or browse trending releases."}
              </p>
              {setActiveView && (
                <button
                  onClick={() => setActiveView('search')}
                  style={{
                    background: 'linear-gradient(135deg, var(--wx-cyan), var(--wx-cyan-dark))',
                    border: 'none',
                    borderRadius: 12,
                    padding: '12px 28px',
                    color: '#080C14',
                    fontWeight: 900,
                    fontSize: 14,
                    cursor: 'pointer',
                    boxShadow: '0 0 20px rgba(0,229,255,0.3)',
                  }}
                >
                  Discover Music
                </button>
              )}
            </div>
          ) : (
            <TrackList tracks={playlistTracks} />
          )}
        </div>

        {/* Add Songs to Custom Playlist */}
        {activeView === "playlist" && (
          <div style={{
            padding: "32px",
            background: "var(--wx-surface-card)",
            borderRadius: 24,
            border: "1px solid var(--wx-border)",
            marginTop: 40,
          }}>
            <h2 style={{ fontSize: isMobile ? 18 : 22, fontWeight: 900, marginBottom: 8, color: "var(--wx-text)" }}>
              Find more songs for this playlist
            </h2>
            <p style={{ fontSize: 13, color: 'var(--wx-text-muted)', marginBottom: 20 }}>
              Search our entire library and click Add to immediately include the track.
            </p>

            <div style={{ position: "relative", maxWidth: 640, marginBottom: 24 }}>
              <input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search songs or artists to add..."
                style={{
                  width: "100%",
                  padding: "14px 18px",
                  borderRadius: 14,
                  border: "1px solid var(--wx-border)",
                  background: "var(--wx-surface)",
                  color: "var(--wx-text)",
                  outline: "none",
                  fontSize: 14,
                  fontWeight: 600,
                  fontFamily: 'inherit',
                }}
              />
              {isSearching && (
                <div style={{ position: "absolute", right: 16, top: "50%", transform: "translateY(-50%)" }}>
                  <Loader2 size={18} color="var(--wx-cyan)" style={{ animation: 'wx-spin 1s linear infinite' }} />
                </div>
              )}
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {searchResults.map((track) => (
                <div
                  key={track.id}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                    padding: "10px 16px",
                    borderRadius: 14,
                    background: "var(--wx-surface)",
                    border: "1px solid var(--wx-border)",
                  }}
                >
                  <img
                    src={track.cover}
                    alt=""
                    onError={(e) => { (e.currentTarget as HTMLImageElement).src = 'https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=200'; }}
                    style={{ width: 44, height: 44, borderRadius: 8, objectFit: 'cover', flexShrink: 0 }}
                  />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 800, color: "var(--wx-text)", overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 14 }}>
                      {track.title}
                    </div>
                    <div style={{ fontSize: 12, color: "var(--wx-text-muted)", overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {track.artist}
                    </div>
                  </div>
                  <button
                    onClick={() => handleAddTrack(track)}
                    disabled={addingIds.has(track.id)}
                    style={{
                      padding: "8px 18px",
                      borderRadius: 10,
                      border: "none",
                      background: addingIds.has(track.id) ? "rgba(255,255,255,0.05)" : "rgba(0,229,255,0.15)",
                      color: addingIds.has(track.id) ? "var(--wx-text-muted)" : "var(--wx-cyan)",
                      fontWeight: 800,
                      cursor: addingIds.has(track.id) ? "default" : "pointer",
                      fontSize: 12,
                      flexShrink: 0,
                      display: 'flex',
                      alignItems: 'center',
                      gap: 6,
                    }}
                  >
                    {addingIds.has(track.id) ? <Loader2 size={14} style={{ animation: 'wx-spin 1s linear infinite' }} /> : <Plus size={14} />}
                    {addingIds.has(track.id) ? "Adding..." : "Add"}
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <style>{`@keyframes wx-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}
